package com.bank.efs.model;

import java.util.HashSet;
import java.util.Set;

// EFS owned by Account A. Lives in a specific VPC; has a resource policy.
public class EfsFileSystem {
    private final String id;
    private final String ownerAccount;
    private final String vpcId;                        // mount target's VPC
    private final Set<String> resourcePolicyAllows = new HashSet<>(); // role ARNs allowed to mount

    public EfsFileSystem(String id, String ownerAccount, String vpcId) {
        this.id = id;
        this.ownerAccount = ownerAccount;
        this.vpcId = vpcId;
    }

    public String getVpcId() { return vpcId; }

    // Account A grants a cross-account role the right to mount (resource policy).
    public void allowMount(String roleArn) { resourcePolicyAllows.add(roleArn); }
    public boolean resourcePolicyAllows(String roleArn) { return resourcePolicyAllows.contains(roleArn); }
}
