    private final String name;
    private final String roleArn;
    private final String vpcId;                       // Lambda's own VPC
    private final Set<String> rolePermissions = new HashSet<>(); // e.g. ClientMount, ec2 ENI perms

    public LambdaFunction(String name, String roleArn, String vpcId) {
        this.name = name;
        this.roleArn = roleArn;
        this.vpcId = vpcId;
    }

    public String getRoleArn() { return roleArn; }
    public String getVpcId() { return vpcId; }

    public void grantPermission(String action) { rolePermissions.add(action); }
    public boolean hasPermission(String action) { return rolePermissions.contains(action); }
}
