package com.bank.efs.model;

// Models VPC peering + security group allowing NFS port 2049 between two VPCs.
public class NetworkPath {
    private final String vpcA;
    private final String vpcB;
    private final boolean peered;
    private final boolean nfsPortOpen;   // TCP 2049 allowed by security groups

    public NetworkPath(String vpcA, String vpcB, boolean peered, boolean nfsPortOpen) {
        this.vpcA = vpcA;
        this.vpcB = vpcB;
        this.peered = peered;
        this.nfsPortOpen = nfsPortOpen;
    }

    // Is there a usable network route between these two VPCs over NFS?
    public boolean connects(String from, String to) {
        boolean sameVpcs = (from.equals(vpcB) && to.equals(vpcA)) || (from.equals(vpcA) && to.equals(vpcB));
        return sameVpcs && peered && nfsPortOpen;
    }
}
