package com.bank.efs.eval;

import com.bank.efs.model.*;
import java.util.logging.Logger;

// Both axes must pass: network connectivity AND authorization.
public class EfsMountEvaluator {
    private static final Logger log = Logger.getLogger(EfsMountEvaluator.class.getName());

    public MountResult evaluate(LambdaFunction lambda, EfsFileSystem efs, NetworkPath network) {
        // AXIS 1 — NETWORK: can the Lambda's VPC reach the EFS mount target's VPC over NFS?
        if (!network.connects(lambda.getVpcId(), efs.getVpcId())) {
            return fail("NETWORK FAIL: no VPC peering / NFS 2049 path — mount TIMES OUT (authz irrelevant)");
        }
        // AXIS 2a — AUTHZ on EFS side: does the EFS resource policy allow this role?
        if (!efs.resourcePolicyAllows(lambda.getRoleArn())) {
            return fail("AUTHZ FAIL: EFS resource policy does not list " + lambda.getRoleArn() + " — ACCESS DENIED");
        }
        // AXIS 2b — AUTHZ on Lambda side: execution role needs EFS client + VPC ENI perms.
        if (!lambda.hasPermission("elasticfilesystem:ClientMount")) {
            return fail("AUTHZ FAIL: execution role lacks elasticfilesystem:ClientMount");
        }
        if (!lambda.hasPermission("ec2:CreateNetworkInterface")) {
            return fail("AUTHZ FAIL: execution role lacks VPC ENI permissions for a VPC-attached Lambda");
        }
        log.info(() -> "MOUNT OK: " + lambda.getRoleArn() + " mounted EFS across accounts");
        return new MountResult(true, "mounted");
    }

    private MountResult fail(String reason) {
        log.severe(() -> reason);
        return new MountResult(false, reason);
    }
}
