package com.bank.efs;

import com.bank.efs.eval.*;
import com.bank.efs.model.*;
import java.util.logging.*;

public class EfsScenarioApplication {
    private static final Logger log = Logger.getLogger(EfsScenarioApplication.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new EfsLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        String roleB = "arn:aws:iam::ACCOUNT_B:role/fraud-lambda-exec";
        EfsFileSystem efs = new EfsFileSystem("fs-0abc", "ACCOUNT_A", "vpc-A");
        LambdaFunction lambda = new LambdaFunction("fraud-lambda", roleB, "vpc-B");
        EfsMountEvaluator evaluator = new EfsMountEvaluator();

        // Attempt 1 — authorization fully granted, but NO network peering. Times out.
        efs.allowMount(roleB);
        lambda.grantPermission("elasticfilesystem:ClientMount");
        lambda.grantPermission("ec2:CreateNetworkInterface");
        NetworkPath noPeering = new NetworkPath("vpc-A", "vpc-B", false, false);
        log.warning(() -> "Attempt 1 (authz only, no network): " + evaluator.evaluate(lambda, efs, noPeering).getReason());

        // Attempt 2 — network peered, but EFS resource policy does NOT allow the role.
        EfsFileSystem efsNoPolicy = new EfsFileSystem("fs-0abc", "ACCOUNT_A", "vpc-A");
        NetworkPath peered = new NetworkPath("vpc-A", "vpc-B", true, true);
        log.warning(() -> "Attempt 2 (network only, no authz): " + evaluator.evaluate(lambda, efsNoPolicy, peered).getReason());

        // Trap A — "just add an SCP". SCP can only RESTRICT, never grant. Still fails.
        log.severe(() -> "Trap SCP: an SCP cannot grant mount rights nor build a peering route — no effect");

        // Trap B — "assume a role in Account A". Role assumption does not authorize an NFS mount.
        log.severe(() -> "Trap role-assume/cross-region: still no network route + EFS authz is by resource policy — fails");

        // Attempt 3 — BOTH axes satisfied. Success.
        MountResult ok = evaluator.evaluate(lambda, efs, peered);
        log.info(() -> "Attempt 3 (network + authz): success=" + ok.isSuccess() + " (" + ok.getReason() + ")");
    }
}

